// Kenya Forest Loss — metrics panel + annual/cumulative chart + export.
// Reads precomputed hectares from loss-stats.json (generated by
// scripts/compute_loss_stats.py from the Hansen lossyear COGs).

const fmt = (v) => Math.round(v).toLocaleString('en-US');

let stats = null;
let chart = null;
let currentKey = 'national';   // 'national' or a region name

function regionNames() {
  return Object.keys(stats.regions).sort(
    (a, b) => stats.regions[b].total_ha - stats.regions[a].total_ha
  );
}

function currentData() {
  return currentKey === 'national'
    ? stats.national_by_year
    : stats.regions[currentKey].by_year;
}

function currentSummary() {
  if (currentKey === 'national') {
    const total = Object.values(stats.national_by_year).reduce((a, b) => a + b, 0);
    let early = 0, late = 0;
    for (const [y, v] of Object.entries(stats.national_by_year)) {
      if (Number(y) <= 2015) early += v; else late += v;
    }
    return { name: 'Kenya (national)', total, early, late };
  }
  const r = stats.regions[currentKey];
  return { name: currentKey, total: r.total_ha, early: r.ha_2001_2015, late: r.ha_2016_2025 };
}

function renderPanel() {
  const s = currentSummary();
  document.getElementById('metric-name').textContent = s.name;
  document.getElementById('metric-total').textContent = fmt(s.total);
  document.getElementById('metric-early').textContent = fmt(s.early);
  document.getElementById('metric-late').textContent = fmt(s.late);
}

function renderChart() {
  const data = currentData();
  const years = Object.keys(data).map(Number).sort((a, b) => a - b);
  const annual = years.map((y) => data[String(y)]);
  let run = 0;
  const cumulative = annual.map((v) => (run += v));

  if (chart) chart.destroy();
  chart = new Chart(document.getElementById('forestLossChart'), {
    type: 'bar',
    data: {
      labels: years,
      datasets: [
        {
          type: 'bar',
          label: 'Annual loss (ha)',
          data: annual,
          backgroundColor: 'rgba(217, 83, 79, 0.7)',
          borderColor: 'rgba(217, 83, 79, 1)',
          borderWidth: 1,
          yAxisID: 'y'
        },
        {
          type: 'line',
          label: 'Cumulative (ha)',
          data: cumulative,
          borderColor: 'rgba(54, 162, 235, 1)',
          backgroundColor: 'rgba(54, 162, 235, 0.2)',
          borderWidth: 2,
          pointRadius: 2,
          fill: false,
          yAxisID: 'y1'
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: true, position: 'bottom', labels: { color: '#e8e8e8', boxWidth: 12 } },
        tooltip: {
          callbacks: {
            label(ctx) { return `${ctx.dataset.label}: ${fmt(ctx.parsed.y)} ha`; },
            footer(items) {
              const i = items[0].dataIndex;
              let c = 0;
              for (let k = 0; k <= i; k++) c += annual[k];
              return `Cumulative to ${years[i]}: ${fmt(c)} ha`;
            }
          }
        }
      },
      scales: {
        x: { grid: { display: false }, ticks: { color: '#9aa4ad' } },
        y: {
          type: 'linear', position: 'left', beginAtZero: true,
          title: { display: true, text: 'Annual (ha)', color: '#9aa4ad' },
          ticks: { color: '#9aa4ad' }
        },
        y1: {
          type: 'linear', position: 'right', beginAtZero: true,
          title: { display: true, text: 'Cumulative (ha)', color: '#9aa4ad' },
          grid: { drawOnChartArea: false },
          ticks: { color: '#9aa4ad' }
        }
      }
    }
  });
}

function populateSelector() {
  const sel = document.getElementById('region-select');
  const opt = (value, label) => {
    const o = document.createElement('option');
    o.value = value;
    o.textContent = label;
    sel.appendChild(o);
  };
  opt('national', 'Kenya (national)');
  for (const name of regionNames()) opt(name, name);
  sel.addEventListener('change', () => {
    currentKey = sel.value;
    renderPanel();
    renderChart();
  });
}

function exportPng() {
  if (!chart) return;
  const a = document.createElement('a');
  a.href = chart.toBase64Image();
  a.download = 'kenya-forest-loss-chart.png';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function exportPdf() {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF('p', 'mm', 'a4');

  // Page 1 — header, map capture, chart.
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(16);
  doc.text('Kenya Forest Cover Loss Assessment', 15, 20);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.text('Hansen/UMD Global Forest Change v1.13 (2001-2025) - 30 m lossyear', 15, 27);

  try {
    const canvas = document.querySelector('#after canvas');
    if (canvas) {
      doc.addImage(canvas.toDataURL('image/png'), 'PNG', 15, 34, 180, 98);
    }
  } catch (e) {
    console.warn('Map capture skipped:', e && e.message);
  }

  if (chart) {
    doc.addImage(chart.toBase64Image(), 'PNG', 15, 138, 180, 95);
  }

  // Page 2 — regional summary table.
  doc.addPage();
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(16);
  doc.text('Regional forest loss summary', 15, 20);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(10);
  doc.text('Loss within each mapped extent (hectares)', 15, 27);

  const body = regionNames().map((n) => {
    const r = stats.regions[n];
    return [n, fmt(r.total_ha), fmt(r.ha_2001_2015), fmt(r.ha_2016_2025)];
  });
  doc.autoTable({
    startY: 34,
    head: [['Region', 'Total loss (ha)', '2001-2015 (ha)', '2016-2025 (ha)']],
    body,
    theme: 'grid',
    headStyles: { fillColor: [40, 116, 81] },
    styles: { fontSize: 9, cellPadding: 3 },
    alternateRowStyles: { fillColor: [245, 245, 245] }
  });

  const pages = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);
    doc.setFont('helvetica', 'italic');
    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text(
      `Page ${i} of ${pages} | Kenya Forest Cover Conservation Project`,
      doc.internal.pageSize.getWidth() / 2,
      290,
      { align: 'center' }
    );
  }

  doc.save('kenya-forest-loss-report.pdf');
}

async function init() {
  try {
    const res = await fetch('loss-stats.json');
    if (!res.ok) throw new Error('loss-stats.json ' + res.status);
    stats = await res.json();
  } catch (e) {
    const el = document.getElementById('metrics');
    if (el) el.innerHTML = 'Metrics unavailable: ' + (e.message || e);
    return;
  }
  populateSelector();
  renderPanel();
  renderChart();
  document.getElementById('btn-export-png').addEventListener('click', exportPng);
  document.getElementById('btn-export-pdf').addEventListener('click', exportPdf);
}

init();
